package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for ListPopulation.iterator().
 */
public class ListPopulation_iterator_TriageGen2Test {

    /**
     * Mock implementation of Chromosome for testing purposes.
     */
    private static class MockChromosome implements Chromosome {
        private final double fitness;

        public MockChromosome(double fitness) {
            this.fitness = fitness;
        }

        @Override
        public double getFitness() {
            return fitness;
        }
    }

    @Test
    public void testIteratorEmpty() {
        ListPopulation population = new ListPopulation(10);
        Iterator<Chromosome> iterator = population.iterator();

        assertNotNull("Iterator should not be null", iterator);
        assertFalse("Iterator should be empty", iterator.hasNext());
    }

    @Test
    public void testIteratorWithElements() {
        Chromosome c1 = new MockChromosome(1.0);
        Chromosome c2 = new MockChromosome(2.0);
        Chromosome c3 = new MockChromosome(3.0);
        List<Chromosome> list = Arrays.asList(c1, c2, c3);

        ListPopulation population = new ListPopulation(list, 10);
        Iterator<Chromosome> iterator = population.iterator();

        assertNotNull("Iterator should not be null", iterator);
        assertTrue("Iterator should have elements", iterator.hasNext());

        int count = 0;
        while (iterator.hasNext()) {
            Chromosome current = iterator.next();
            assertEquals("Element mismatch", list.get(count), current);
            count++;
        }

        assertEquals("Should have iterated over 3 elements", 3, count);
        assertFalse("Iterator should be exhausted", iterator.hasNext());
    }

    @Test
    public void testIteratorAfterModification() {
        Chromosome c1 = new MockChromosome(1.0);
        ListPopulation population = new ListPopulation(5);
        population.addChromosome(c1);

        Iterator<Chromosome> iterator = population.iterator();
        assertTrue(iterator.hasNext());
        assertEquals(c1, iterator.next());

        // Add another chromosome to the population
        population.addChromosome(new MockChromosome(2.0));

        // Note: Since ListPopulation uses the underlying list's iterator, 
        // modifications to the list after the iterator is created typically 
        // result in ConcurrentModificationException if the underlying list is an ArrayList.
        // This test ensures the iterator behaves as the underlying collection's iterator.

        Iterator<Chromosome> newIterator = population.iterator();
        int count = 0;
        while (newIterator.hasNext()) {
            newIterator.next();
            count++;
        }
        assertEquals("Should reflect updated size", 2, count);
    }

    @Test
    public void testIteratorWithSetChromosomes() {
        ListPopulation population = new ListPopulation(10);
        Chromosome c1 = new MockChromosome(1.0);
        Chromosome c2 = new MockChromosome(2.0);

        population.setChromosomes(new ArrayList<>(Arrays.asList(c1, c2)));
        Iterator<Chromosome> iterator = population.iterator();

        assertTrue(iterator.hasNext());
        assertEquals(c1, iterator.next());
        assertTrue(iterator.hasNext());
        assertEquals(c2, iterator.next());
        assertFalse(iterator.hasNext());
    }

    @Test
    public void testIteratorWithNullList() {
        // Testing behavior when the internal list might be manipulated via setChromosomes
        ListPopulation population = new ListPopulation(10);
        // Depending on implementation, setChromosomes might allow null or empty.
        // Assuming it follows standard ListPopulation behavior:
        population.setChromosomes(new ArrayList<>());
        Iterator<Chromosome> iterator = population.iterator();
        assertFalse(iterator.hasNext());
    }
}
